command_captures.command:
node - <<'NODE'
const fs=require('fs'),crypto=require('crypto');
const sha=p=>crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex');
const path='docs/remediation/design/W24.01/baseline-r2.json',baseline=JSON.parse(fs.readFileSync(path));
const owned=new Set(baseline.owned.map(x=>x.path)),protectedPins=baseline.pins.filter(x=>!owned.has(x.path));
const mismatches=protectedPins.filter(x=>sha(x.path)!==x.sha256).map(x=>x.path);
const result={final_source_stop:{at:new Date().toISOString(),files:[...owned].map(path=>({path,sha256:sha(path)}))},protected_source_comparison:{expected:protectedPins.length,matched:protectedPins.length-mismatches.length,mismatches},references:[path,'docs/remediation/design/W24.01/plan-r2.md','docs/remediation/evidence/W24.01/admission-r2.json'].map(path=>({path,sha256:sha(path)}))};
console.log(JSON.stringify(result,null,2));if(mismatches.length)process.exitCode=1;
NODE

